      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n11/14~17) 중학생 학부모님께 ]_중학생 대상 게임 조사_중학생 자녀 소개 부탁드립니다^^\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.21. 19:10\n조회 42\n구독\n11/14~17) 중학생 학부모님께 ]_중학생 대상 게임 조사_중학생 자녀 소개 부탁드립니다^^\n*조사 조건\n* 현재 중학교 재학(1학년~3학년) 대상으로 게임 조사를 실시 합니다\n* 진행은 주말에(토,일) 진행 되며 충정로에 있는 리서치 사무실에서 진행됩니다.안심하셔도 됩니다^^(같이 오셔도 됩니다)\n* 중학생 자녀를 두신분 자녀분 참여 가능하시면 신청 해주시면 \"선정링크\"드리겠습니니다\nG1_PC_MOBA/RPG 게임 유저\nG2_PC_FPS/RPG 게임 유저\nG3_PC게임보다 모바일 게임을 주로 하는 이용자\n**좌담회 시작전 게임에 관련된 과제물 작성후(일부) 좌담회 참석\n***선정지는 링크로 작성됩니다^^\n진행 날짜/시간 11월 14일(토요일)/11월15일(일요일)_10시30분/2시\n진행 날짜/시간 11월16일(월)~11월17일(화)_저녁 7시\n소요시간 2시간\n조사 장소 충정로역\n사례비 참석비_7만원/과제물작성완료시_3만원 추가 지급\n*신청 하실때 이 방법으로 보내주세요\n*신청자 부모님_이름/연락처/성별/\n*자녀_성별/만나이/거주지역/학교명,학년/주로이용게임기기/최근 1개월이내 플레이한 게임_모두 적어주세요/주게임횟수/1일게임시간/최근 3개월이내 TFT전략적게임플레이 경험여부_있으면 게임명 기입,없으면 없다/이메일주소/해당 그룹\n작성_예시)\n*학부모_이미나/010-1111-1234/여\n*자녀_여/15세/마포구 대흥동/서울여중,2학년/PC로 주로 한다/발로란트,베틀그라운드,던전앤파이터,로켓레이싱/주 6일/1일 2시간/TFT_오토체스,하스스톤/oppo@naver.com/G2\nhttps://forms.gle/U1NA66T59Txi1yQv6\n좋아요\n0\n송파구에서 핫한 진짜 동네 이야기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.10.21. 19:54 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n10~11월 중) 간병서비스 이용자 좌담회\n좌담회알바좌담회카페\n26.10.21.\n댓글\n1\n11/14~17) 중학생 학부모님께 ]_중학생 대상 게임 조사_중학생 자녀 소개 부탁드립니다^^\n좌담회알바좌담회카페\n26.10.21.\n댓글\n1\n고등학생]게임 조사_MOBA,FPS/RPG게임유저/모바일로 게임 하는분  모두 대상!!!\n좌담회알바좌담회카페\n26.10.21.\n댓글\n1\n중학생]게임 조사_MOBA,FPS/RPG게임유저/모바일로 게임 하는분 모두 대상!!!\n좌담회알바좌담회카페\n26.10.21.\n댓글\n1\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
